417|/** Gentle count-up, used for the community tally and each card's minutes. */
418|function CountUp({ value, className = 'tally-num' }) {
419|  // Default to the real value so the number is correct even if we never animate.
420|  const [shown, setShown] = useState(value);
421|  useEffect(() => {
422|    const reduce = window.matchMedia?.('(prefers-reduced-motion: reduce)').matches;
423|    // In a background tab requestAnimationFrame is suspended, so skip the
424|    // animation entirely rather than risk showing a stale 0.
425|    if (reduce || document.hidden) { setShown(value); return undefined; }
426|
427|    let raf;
428|    let done = false;
429|    const dur = 1350;
430|    const start = performance.now();
431|    const tick = (t) => {
432|      const p = Math.min(1, (t - start) / dur);
433|      const eased = 1 - Math.pow(1 - p, 3);
434|      setShown(Math.round(value * eased));
435|      if (p < 1) raf = requestAnimationFrame(tick);
436|      else done = true;
437|    };
438|    setShown(0);
439|    raf = requestAnimationFrame(tick);
440|    // Safety net: if rAF is throttled mid-flight, snap to the final value.
441|    const fallback = setTimeout(() => { if (!done) setShown(value); }, dur + 400);
442|
443|    return () => { cancelAnimationFrame(raf); clearTimeout(fallback); };
444|  }, [value]);
445|  return <span className={className}>{shown.toLocaleString()}</span>;
446|}
