448|/**
449| * Fade + rise a section in when it first scrolls into view. The class is added
450| * once and kept — content must never fade back out while someone reads it.
451| * Reduced motion (and any browser without IntersectionObserver) shows the
452| * section immediately.
453| */
454|function Reveal({ children, delay = 0 }) {
455|  const ref = useRef(null);
456|  const [seen, setSeen] = useState(false);
457|  useEffect(() => {
458|    const el = ref.current;
459|    const reduce = window.matchMedia?.('(prefers-reduced-motion: reduce)').matches;
460|    if (!el || reduce || typeof IntersectionObserver === 'undefined') { setSeen(true); return undefined; }
461|    // A healthy observer always reports the INITIAL state within a frame or
462|    // two, even for off-screen elements. If it never calls back at all, the
463|    // environment has IO suspended — reveal rather than stay invisible.
464|    let reported = false;
465|    const io = new IntersectionObserver(
466|      ([entry]) => {
467|        reported = true;
468|        if (entry.isIntersecting) { setSeen(true); io.disconnect(); }
469|      },
470|      { rootMargin: '0px 0px -8% 0px', threshold: 0.08 }
471|    );
472|    io.observe(el);
473|    const failsafe = setTimeout(() => { if (!reported) setSeen(true); }, 1500);
474|    return () => { io.disconnect(); clearTimeout(failsafe); };
475|  }, []);
476|  return (
477|    <div
478|      ref={ref}
479|      className={`reveal ${seen ? 'in' : ''}`}
480|      style={delay ? { transitionDelay: `${delay}ms` } : undefined}
481|    >
482|      {children}
483|    </div>
484|  );
