1300|function useCountdown(iso) {
1301|  const [now, setNow] = useState(() => Date.now());
1302|  useEffect(() => {
1303|    const t = setInterval(() => setNow(Date.now()), 60000);
1304|    return () => clearInterval(t);
1305|  }, []);
1306|  if (!iso) return null;
1307|  let diff = new Date(iso).getTime() - now;
1308|  if (diff <= 0) return null;
1309|  const d = Math.floor(diff / 86400000); diff -= d * 86400000;
1310|  const h = Math.floor(diff / 3600000); diff -= h * 3600000;
1311|  const m = Math.floor(diff / 60000);
1312|  if (d > 0) return `${d}d ${h}h`;
1313|  if (h > 0) return `${h}h ${m}m`;
1314|  return `${m}m`;
