/** Live mini card preview — updates in real-time as the form is filled. */
function LivePreview({
  refuahName, refuahNameEnglish, motherName, relation,
  dedicationType, category, categoryAmount, showCategory,
  message, tehillim,
  beforeMinutes, afterExtraMinutes, afterOn,
  weeks, runningTotal,
}) {
  const ded = config.dedications[dedicationType] || config.dedications.refuah;
  const cat = config.categories.find((c) => c.key === category);
  const displayName = refuahName || '';
  const hasAnything = refuahName || runningTotal > 0 || category || message || tehillim;

  if (!hasAnything) {
    return (
      <div className="live-preview" aria-hidden="true">
        <div className="lp-label">Preview</div>
        <div className="lp-hint">Fill in the form to see your card</div>
      </div>
    );
  }

  return (
    <div className="live-preview" aria-label="Live card preview">
      <div className="lp-label">Preview</div>
      <div className="lp-card">
        <div className="card-top">
          <div>
            <div className="dedication">{ded.prefix}</div>
            <div className="name" dir="auto">{displayName}</div>
            {refuahNameEnglish && <div className="name-en">{refuahNameEnglish}</div>}
          </div>
          <div className="minutes">
            <b>{runningTotal || '—'}</b>
            <small>extra min / week</small>
          </div>
        </div>
        <div className="card-bar" aria-hidden="true">
          <span style={{ width: `${Math.max(4, Math.min(100, (runningTotal / 30) * 100))}%` }} />
        </div>
        <div className="ends-row">
          {beforeMinutes > 0 && <span className="end-pill before">🕯 +{beforeMinutes} early</span>}
          {afterOn && afterExtraMinutes > 0 && <span className="end-pill after">✦ +{afterExtraMinutes} late</span>}
          {category && showCategory && (
            <span className="end-pill category">
              {categoryAmount ? `${categoryAmount} · ${cat?.pill || category}` : cat?.pill || category}
            </span>
          )}
          {weeks > 0 && <span className="end-pill count">{weeks} {weeks === 1 ? 'week' : 'weeks'}</span>}
        </div>
        {message && <div className="card-message">{message}</div>}
        {tehillim && (
          <div className="card-tehillim">
            <span className="ct-label">Tehillim</span>
            <span className="ct-item">{tehillim}</span>
          </div>
        )}
      </div>
    </div>
  );
}

