const nameRef = useRef(null);
const motherRef = useRef(null);
const caretRef = useRef(null);
const wizardRef = useRef(null);

// Auto-detect Hebrew: if the user types a Hebrew character while the toggle
// is on English, flip it — but only if they haven't manually chosen English.
const nameLangManual = useRef(false);
useEffect(() => {
  if (nameLangManual.current || nameLang !== 'en' || !refuahName) return;
  if (/[\u0590-\u05FF]/.test(refuahName.slice(-1))) {
    setNameLang('he');
  }
}, [refuahName, nameLang]);

// ---- Voice input (Web Speech API) ----
const micSupported = typeof window !== 'undefined' && (window.SpeechRecognition || window.webkitSpeechRecognition);
const [micFor, setMicFor] = useState(null); // null | 'name' | 'mother'
const micRecog = useRef(null);

function startMic(field) {
  if (!micSupported) return;
  const SpeechRecognition = window.SpeechRecognition || window.webkitSpeechRecognition;
  const recog = new SpeechRecognition();
  recog.lang = nameLang === 'he' ? 'he-IL' : 'en-US';
  recog.interimResults = false;
  recog.maxAlternatives = 1;

  recog.onresult = (event) => {
    const transcript = event.results[0][0].transcript;
    // For English, also trim any trailing period the engine may add.
    const clean = nameLang === 'en' ? transcript.replace(/\.$/, '').trim() : transcript.trim();
    const el = field === 'mother' ? motherRef.current : nameRef.current;
    const start = el?.selectionStart ?? (field === 'mother' ? motherName.length : refuahName.length);
    const end = el?.selectionEnd ?? (field === 'mother' ? motherName.length : refuahName.length);
    caretRef.current = start + clean.length;
    if (field === 'mother') {
      setMotherName(motherName.slice(0, start) + clean + motherName.slice(end));
    } else {
      // If Hebrew was spoken while toggle is on English, flip the toggle.
      if (nameLang === 'en' && /[\u0590-\u05FF]/.test(clean)) {
        setNameLang('he');
        nameLangManual.current = false;
      }
      setRefuahName(refuahName.slice(0, start) + clean + refuahName.slice(end));
    }
  };

  recog.onerror = () => { setMicFor(null); };
  recog.onend = () => { setMicFor(null); };

  micRecog.current = recog;
  recog.start();
  setMicFor(field);
}

function stopMic() {
  if (micRecog.current) {
    micRecog.current.stop();
    micRecog.current = null;
  }
  setMicFor(null);
}

