.mic-row { display: flex; gap: 8px; align-items: center; }
.mic-row input { flex: 1; }
.mic-btn {
  flex-shrink: 0;
  width: 44px; height: 44px;
  border-radius: 50%;
  border: 1px solid var(--line);
  background: var(--bg-elev);
  font-size: 1.2rem;
  cursor: pointer;
  display: flex; align-items: center; justify-content: center;
  transition: all 0.22s var(--ease);
  padding: 0;
}
.mic-btn:hover {
  border-color: var(--gold);
  box-shadow: 0 0 18px -6px rgba(235, 207, 138, 0.5);
  transform: scale(1.06);
}
.mic-btn.listening {
  border-color: #e08a8a;
  background: rgba(224, 138, 138, 0.1);
  animation: micPulse 0.9s ease-in-out infinite;
}
@keyframes micPulse {
  0%, 100% { box-shadow: 0 0 0 0 rgba(224, 138, 138, 0.5); }
  50%      { box-shadow: 0 0 0 10px rgba(224, 138, 138, 0); }
}

